# Generated by manage.py generate_test_cases.
from bs4 import BeautifulSoup

from bloomerp.tests.base import (
    BloomerpWidgetTestCase,
    WidgetOperation,
    WidgetScenario,
)
from bloomerp.widgets.booking_location_widget import (
    CREATE_BOOKING_CONFERENCE,
    BookingLocationWidget,
)


class TestBookingLocationWidget(BloomerpWidgetTestCase):
    widget_class = BookingLocationWidget

    def get_test_scenarios(self) -> list[WidgetScenario[BookingLocationWidget]]:
        """Exercise native controls and their shared stored value."""
        return [WidgetScenario(
            name="Text and the meeting checkbox submit a single location",
            operations=[
                WidgetOperation(
                    name="Render automatic meeting selection",
                    execute=self.render_meeting,
                    result_validators=self.meeting_is_checked,
                ),
                WidgetOperation(
                    name="Prefer a checked meeting option over text",
                    execute=self.extract_meeting,
                    result_validators=self.is_meeting_value,
                ),
                WidgetOperation(
                    name="Accept manual locations with the checkbox clear",
                    execute=self.extract_manual_location,
                    result_validators=self.is_manual_location,
                ),
            ],
        )]

    def render_meeting(self, widget: BookingLocationWidget) -> str:
        """Render a saved meeting setting back to its native controls."""
        return widget.render("location", CREATE_BOOKING_CONFERENCE)

    def meeting_is_checked(self, rendered: str) -> bool:
        """Show a blank input and a checked meeting option for the reserved value."""
        html = BeautifulSoup(rendered, "html.parser")
        text = html.select_one('input[name="location"]')
        return (
            text is not None
            and not text.get("value")
            and html.select_one('input[name="location__meeting"][checked]') is not None
        )

    def extract_meeting(self, widget: BookingLocationWidget) -> str | None:
        """Read a checked control even if a manual location was also submitted."""
        return widget.value_from_datadict(
            {"location": "Room 4", "location__meeting": "on"}, {}, "location"
        )

    def is_meeting_value(self, value: str | None) -> bool:
        """Confirm the checkbox maps to the persisted meeting setting."""
        return value == CREATE_BOOKING_CONFERENCE

    def extract_manual_location(self, widget: BookingLocationWidget) -> str | None:
        """Read plain text from the input with no meeting checkbox selected."""
        return widget.value_from_datadict({"location": "Room 4"}, {}, "location")

    def is_manual_location(self, value: str | None) -> bool:
        """Retain the organizer's manually entered location."""
        return value == "Room 4"
